return (function () {
var cx = api.ctx, W = api.width, H = api.height;
const P = 14, D = 2.6, LV = [0.18, 0.5, 0.8, 1];
const INK = '#04204B', SEC = '#3D5F91', FAINT = '#8098BC', BLUE = '#0B4FC0', WARM = '#B4552F', TEAL = '#138374';
const rng = function (s) { return function () { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; };
const rn = rng(11);
