for (let i = 0; i < 8; i++) NZ.push([]);
for (let i = 0; i < 8; i++) for (let j = i; j < 8; j++) { const v = 0.12 + 0.76 * rn(); NZ[i][j] = v; NZ[j][i] = v; }
const TG = [[-0.6,-0.2],[0.3,0.5],[-0.3,0.7],[0.5,-0.3],[-0.1,-0.1],[0.7,0.6],[-0.7,0.4],[0.1,-0.8],[0.6,-0.7],[-0.4,-0.6],[0.2,0.1],[-0.8,-0.8]];
const HP = [];
for (let i = 0; i < 12; i++) {
  if (i < 5) HP.push([-0.38, -0.9 + i * 0.4]);
  else if (i === 5) HP.push([-0.17, 0.98]);
  else if (i === 6) HP.push([0.17, 0.98]);
  else HP.push([0.38, 0.6 - (i - 7) * 0.4]);
}
const clamp = function (x, a, b) { return Math.max(a, Math.min(b, x)); };
const ease = function (t) { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); };
const lerp = function (a, b, t) { return a + (b - a) * t; };

function T(txt, x, y, size, col, al, maxW, bold) {
