  cx.font = (bold ? 'bold ' : '') + s + 'px sans-serif';
  while (s > 11 && cx.measureText(txt).width > maxW) { s--; cx.font = (bold ? 'bold ' : '') + s + 'px sans-serif'; }
  const w = cx.measureText(txt).width;
