}
function rr(x, y, w, h, r) {
  cx.beginPath(); cx.moveTo(x + r, y);
  cx.arcTo(x + w, y, x + w, y + h, r); cx.arcTo(x + w, y + h, x, y + h, r);
  cx.arcTo(x, y + h, x, y, r); cx.arcTo(x, y, x + w, y, r); cx.closePath();
}
function head(x, y, ang, col) {
  cx.fillStyle = col; cx.beginPath(); cx.moveTo(x, y);
  cx.lineTo(x - 7 * Math.cos(ang - 0.4), y - 7 * Math.sin(ang - 0.4));
  cx.lineTo(x - 7 * Math.cos(ang + 0.4), y - 7 * Math.sin(ang + 0.4)); cx.closePath(); cx.fill();
}
function arrow(a, b, col, lw) {
  cx.strokeStyle = col; cx.lineWidth = lw; cx.beginPath(); cx.moveTo(a[0], a[1]); cx.lineTo(b[0], b[1]); cx.stroke();
  head(b[0], b[1], Math.atan2(b[1] - a[1], b[0] - a[0]), col);
}
function curve(p, col, lw) {
  cx.strokeStyle = col; cx.lineWidth = lw; cx.beginPath(); cx.moveTo(p[0][0], p[0][1]);
  cx.bezierCurveTo(p[1][0], p[1][1], p[2][0], p[2][1], p[3][0], p[3][1]); cx.stroke();
  head(p[3][0], p[3][1], Math.atan2(p[3][1] - p[2][1], p[3][0] - p[2][0]), col);
