function bz(p, t) {
  const u = 1 - t, a = u * u * u, b = 3 * u * u * t, c = 3 * u * t * t, d = t * t * t;
  return [a * p[0][0] + b * p[1][0] + c * p[2][0] + d * p[3][0], a * p[0][1] + b * p[1][1] + c * p[2][1] + d * p[3][1]];
}
function dot(p, col, r) { cx.fillStyle = col; cx.beginPath(); cx.arc(p[0], p[1], r, 0, 6.2832); cx.fill(); }

const CAPS = ['pass 1: first guess from the inputs', 'passes 2–4: the trunk refines its own output', 'gradients flow only through the last pass in training', 'c = (s, z) handed to the denoiser'];
const CST = [0, 2.6, 8.0, 10.4];

function draw(c, w, h, time, dt) {
  cx = c; W = w; H = h;
  cx.fillStyle = '#ffffff'; cx.fillRect(0, 0, W, H);
  const tt = time % P;
  const running = tt < 4 * D;
  const k = running ? Math.floor(tt / D) : 3;
  const ti = running ? (tt - k * D) / D : 1;
  let q;
  if (running) { const pl = k === 0 ? 0 : LV[k - 1]; q = pl + (LV[k] - pl) * ease((ti - 0.5) / 0.35); }
  else if (tt < 13.2) q = 1;
  else q = 1 - ease((tt - 13.2) / 0.8);
  let fa = 0;
  if (!running) fa = ease((tt - 10.4) / 0.6) * (tt > 13.2 ? 1 - ease((tt - 13.2) / 0.6) : 1);
  const gradPh = tt >= 8.0 && tt < 10.4;

  const wide = W >= 560;
  let cy, inb, plus, tr, R, O, pA, pB, m, mx, my, chx, outS, outE, cnt, sgp, olab, olal;
  if (wide) {
    cy = 0.42 * H; inb = [0.03 * W, cy - 30, 0.2 * W, 60]; plus = [0.29 * W, cy]; tr = [0.34 * W, cy - 40, 0.2 * W, 80];
    m = Math.min(0.15 * W, 135); mx = 0.6 * W; my = cy - m / 2; chx = mx + m + 0.07 * W;
    R = [0.34 * W, cy + 85, 0.2 * W, 46]; const rc = R[1] + R[3] / 2;
    O = [tr[0] + tr[2] + 0.03 * W, cy]; outS = [tr[0] + tr[2], cy]; outE = [mx - 4, cy];
    pA = [O, [O[0], O[1] + (rc - O[1]) * 0.6], [O[0], rc], [R[0] + R[2], rc]];
    pB = [[R[0], rc], [R[0] - 0.06 * W, rc], [plus[0], cy + (rc - cy) * 0.55], [plus[0], cy + 10]];
    cnt = [0.03 * W, rc]; sgp = [R[0] + R[2] / 2, R[1] + R[3] + 14]; olab = [(outS[0] + outE[0]) / 2, cy - 13]; olal = 'center';
  } else {
    cy = 76; inb = [0.03 * W, 54, 0.4 * W, 44]; plus = [0.5 * W, 76]; tr = [0.57 * W, 54, 0.4 * W, 44];
    m = 0.32 * W; mx = 0.77 * W - m / 2; my = 190; chx = 0.06 * W;
    R = [0.33 * W, 115, 0.34 * W, 38];
    O = [0.77 * W, 122]; outS = [0.77 * W, 98]; outE = [0.77 * W, my - 14];
    pA = [O, [0.77 * W, 130], [0.72 * W, 134], [0.67 * W, 134]];
    pB = [[0.5 * W, 115], [0.5 * W, 108], [0.5 * W, 92], [0.5 * W, 86]];
    cnt = [0.03 * W, 134]; sgp = [0.42 * W, 171]; olab = [0.77 * W + 8, 152]; olal = 'left';
  }
  const my2 = my + m / 2;

  let ci = 0; for (let i = 0; i < 4; i++) if (tt >= CST[i]) ci = i;
  let ca = clamp((tt - CST[ci]) / 0.4, 0, 1);
  if (tt > 13.5) ca *= 1 - (tt - 13.5) / 0.5;
  cx.globalAlpha = ca;
  T(CAPS[ci], W / 2, 22, 13, ci === 2 ? WARM : INK, 'center', W - 16, true);
  cx.globalAlpha = 1;

  const recAct = running && k < 3 && ti > 0.72;
  cx.setLineDash([5, 3]);
  curve(pA, recAct ? WARM : 'rgba(180,85,47,0.55)', recAct ? 2.2 : 1.4);
  curve(pB, recAct ? WARM : 'rgba(180,85,47,0.55)', recAct ? 2.2 : 1.4);
  cx.setLineDash([]);
  arrow([inb[0] + inb[2], cy], [plus[0] - 9, cy], FAINT, 1.5);
  arrow([plus[0] + 9, cy], [tr[0], cy], FAINT, 1.5);
  arrow(outS, outE, fa > 0 ? TEAL : INK, fa > 0 ? 2.5 : 1.5);
  T('s, z', olab[0], olab[1], 12, SEC, olal, 60, false);
  const ax = wide ? [mx + m + 3, my2] : [mx - 3, my2];
  const bx = wide ? [chx - 3, my2] : [chx + m + 3, my2];
  arrow(ax, bx, FAINT, 1.5);
  if (Math.abs(ax[0] - bx[0]) >= 60) T('distogram', (ax[0] + bx[0]) / 2, my2 - 10, 11, SEC, 'center', 70, false);

  rr(inb[0], inb[1], inb[2], inb[3], 6); cx.fillStyle = '#F4F7FC'; cx.fill(); cx.strokeStyle = SEC; cx.lineWidth = 1.3; cx.stroke();
  T('input embeddings', inb[0] + inb[2] / 2, inb[1] + inb[3] / 2 - 8, 12, INK, 'center', inb[2] - 6, false);
  T('s_inputs, z_init', inb[0] + inb[2] / 2, inb[1] + inb[3] / 2 + 9, 11, SEC, 'center', inb[2] - 6, false);
  const pulse = running ? Math.sin(Math.PI * clamp((ti - 0.35) / 0.35, 0, 1)) : 0;
  rr(tr[0], tr[1], tr[2], tr[3], 8); cx.fillStyle = '#EEF3FB'; cx.fill();
  cx.fillStyle = 'rgba(11,79,192,' + (0.22 * pulse).toFixed(3) + ')'; cx.fill();
  cx.strokeStyle = gradPh ? WARM : INK; cx.lineWidth = gradPh ? 3 : 1.6; cx.stroke();
  T('Pairformer', tr[0] + tr[2] / 2, tr[1] + tr[3] / 2 - 8, 13, INK, 'center', tr[2] - 8, true);
  T('stack', tr[0] + tr[2] / 2, tr[1] + tr[3] / 2 + 9, 13, INK, 'center', tr[2] - 8, true);
  if (running && ti > 0.35 && ti < 0.7) {
    const pr = (ti - 0.35) / 0.35;
    cx.fillStyle = BLUE; cx.fillRect(tr[0] + 8, tr[1] + tr[3] - 7, (tr[2] - 16) * pr, 3);
  }
  rr(R[0], R[1], R[2], R[3], 6); cx.fillStyle = '#FBF3EF'; cx.fill(); cx.strokeStyle = WARM; cx.lineWidth = recAct ? 2 : 1.3; cx.stroke();
  T('recycle', R[0] + R[2] / 2, R[1] + R[3] / 2 - 8, 12, WARM, 'center', R[2] - 6, true);
  T('LayerNorm + linear', R[0] + R[2] / 2, R[1] + R[3] / 2 + 9, 11, SEC, 'center', R[2] - 6, false);
  const lastPass = !running || k === 3;
  T(lastPass ? '∇ flows (last pass)' : 'stop-gradient', sgp[0], sgp[1], 11, lastPass ? WARM : FAINT, 'center', 120, false);

  cx.globalAlpha = (k === 0 && running) ? 0.35 : 1;
  const glow = (running && k > 0 && ti < 0.3) ? 1 - ti / 0.3 : 0;
  if (glow > 0) { cx.fillStyle = 'rgba(180,85,47,' + (0.3 * glow).toFixed(3) + ')'; cx.beginPath(); cx.arc(plus[0], plus[1], 14, 0, 6.2832); cx.fill(); }
  cx.fillStyle = '#fff'; cx.beginPath(); cx.arc(plus[0], plus[1], 9, 0, 6.2832); cx.fill();
  cx.strokeStyle = INK; cx.lineWidth = 1.5; cx.stroke();
  cx.beginPath(); cx.moveTo(plus[0] - 5, plus[1]); cx.lineTo(plus[0] + 5, plus[1]); cx.moveTo(plus[0], plus[1] - 5); cx.lineTo(plus[0], plus[1] + 5); cx.stroke();
  cx.globalAlpha = 1;

  if (running && ti < 0.35) { const u = ease(ti / 0.35); dot([lerp(inb[0] + inb[2], tr[0], u), cy], BLUE, 4); }
  if (running && k < 3 && ti > 0.72) {
    const u = (ti - 0.72) / 0.28;
    dot(u < 0.5 ? bz(pA, u * 2) : bz(pB, (u - 0.5) * 2), WARM, 4);
  }
  if (running && ti > 0.68 && ti < 0.85) { const u = (ti - 0.68) / 0.17; dot([lerp(outS[0], outE[0], u), lerp(outS[1], outE[1], u)], BLUE, 4); }

  const pk = running ? k + 1 : 4;
  T('pass ' + pk + ' / 4', cnt[0], cnt[1], 14, INK, 'left', 90, true);

  const cs = m / 8;
  for (let i = 0; i < 8; i++) for (let j = 0; j < 8; j++) {
    const band = Math.exp(-Math.abs(i - j) / 1.1);
    const blk = ((i <= 2 && j >= 5) || (j <= 2 && i >= 5)) ? 0.85 : 0;
    const tv = Math.max(band, blk);
    const nz = NZ[i][j] + (1 - q) * 0.1 * Math.sin(time * 2.5 + i * 3 + j * 5);
    const v = clamp((1 - q) * nz + q * tv, 0, 1);
    const g = Math.round(245 - v * 225);
    cx.fillStyle = 'rgb(' + g + ',' + g + ',' + Math.min(255, g + Math.round(q * 25)) + ')';
