  cx.strokeStyle = fa > 0 ? TEAL : FAINT; cx.lineWidth = fa > 0 ? 2.2 : 1.2; cx.strokeRect(chx, my, m, m);
  const ccx = chx + m / 2, ccy = my + m / 2, sc = m * 0.42;
  const pts = [];
  for (let i = 0; i < 12; i++) {
    const wob = (1 - q) * 0.05 * Math.sin(time * 2 + i * 1.7);
    pts.push([ccx + (lerp(TG[i][0], HP[i][0], q) + wob) * sc, ccy - (lerp(TG[i][1], HP[i][1], q) + wob) * sc]);
