  for (let i = 1; i < 12; i++) cx.lineTo(pts[i][0], pts[i][1]);
  cx.stroke();
  for (let i = 0; i < 12; i++) {
    const f = i / 11;
    cx.fillStyle = 'rgb(' + Math.round(lerp(11, 180, f)) + ',' + Math.round(lerp(79, 85, f)) + ',' + Math.round(lerp(192, 47, f)) + ')';
    cx.beginPath(); cx.arc(pts[i][0], pts[i][1], 3.6, 0, 6.2832); cx.fill();
  }
  T('implied chain', chx + m / 2, my + m + 14, 12, INK, 'center', m + 20, false);

  if (fa > 0) {
    cx.globalAlpha = fa;
    const pw = Math.min(W - 24, 280), ph = 28, px = W / 2 - pw / 2, py = H - 44;
    rr(px, py, pw, ph, 14); cx.fillStyle = '#EAF6F3'; cx.fill(); cx.strokeStyle = TEAL; cx.lineWidth = 1.5; cx.stroke();
    T('c = (s, z)  →  denoiser', W / 2, py + ph / 2, 13, TEAL, 'center', pw - 16, true);
    cx.globalAlpha = 1;
  }
}
return { draw: draw };
})();
